mapper.select:
SELECT
,c.embedding <=> CAST(#{vector} AS vector) AS distance,
AND c.embedding IS NOT NULL AND c.embedding_model=#{model} AND c.embedding_dimensions=#{dimensions} AND e.model=c.embedding_model AND e.dimensions=c.embedding_dimensions AND c.embedding_content_hash=encode(sha256(convert_to(c.content,'UTF8')),'hex') ORDER BY c.embedding <=> CAST(#{vector} AS vector),c.id LIMIT #{topK}
